result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_search.py", "content": "import random

from search import lower_bound


def reference(a, x):
    """Linear-scan oracle: first i with a[i] >= x, else len(a)."""
    for i, v in enumerate(a):
        if v >= x:
            return i
    return len(a)


# --- The bug-exposing test -------------------------------------------------

def test_duplicates_first_occurrence():
    # Docstring promises the FIRST index i with a[i] >= x.
    # With duplicates of x, that is index 1, not the end of the run.
    assert lower_bound([1, 2, 2, 3], 2) == 1
    assert lower_bound([2, 2, 2], 2) == 0


# --- Edge cases ------------------------------------------------------------

def test_empty_list():
    assert lower_bound([], 5) == 0


def test_x_smaller_than_everything():
    assert lower_bound([10, 20, 30], 5) == 0


def test_x_larger_than_everything():
    assert lower_bound([10, 20, 30], 99) == 3


def test_x_between_elements():
    assert lower_bound([10, 20, 30], 15) == 1


def test_all_equal_below():
    assert lower_bound([7, 7, 7, 7], 8) == 4


def test_all_equal_above():
    assert lower_bound([7, 7, 7, 7], 6) == 0


def test_single_element():
    assert lower_bound([5], 5) == 0
    assert lower_bound([5], 6) == 1
    assert lower_bound([5], 4) == 0


# --- Seeded fuzz against linear-scan reference -----------------------------

def test_fuzz_against_reference():
    rng = random.Random(42)
    for _ in range(2000):
        n = rng.randint(0, 50)
        # Small value range => lots of duplicates on purpose
        a = sorted(rng.randint(-5, 5) for _ in range(n))
        x = rng.randint(-7, 7)
        assert lower_bound(a, x) == reference(a, x), (
            f"lower_bound({a!r}, {x!r}) != {reference(a, x)!r}"
        )
